28	
29	    /** A due date set by hand can be at most this many days after the issue date. */
30	    public static final int MAX_DUE_DAYS = 120;
31	
32	    /** Payments that leave less than this still due have the rest written off. */
33	    public static final BigDecimal WRITE_OFF_LIMIT = new BigDecimal("1.00");
34	
35	    /** A part payment must be at least this share of the grand total, unless it settles the invoice. */
36	    public static final BigDecimal MINIMUM_PART_SHARE = new BigDecimal("0.10");
37	
38	    @Id
39	    @GeneratedValue(strategy = GenerationType.IDENTITY)
40	    private Long id;
41	
42	    @Column(name = "client_id")
43	    private Long clientId;
44	
45	    @Enumerated(EnumType.STRING)
46	    private InvoiceStatus status;
47	
48	    @Column(name = "issue_date")
49	    private LocalDate issueDate;
50	
51	    @Column(name = "due_date")
52	    private LocalDate dueDate;
53	
54	    @Column(name = "manual_due_date")
55	    private boolean manualDueDate;
56	
57	    @Column(name = "discount_pct")
58	    private BigDecimal discountPct = BigDecimal.ZERO;
59	
60	    @Column(name = "discount_amount")
61	    private BigDecimal discountAmount = BigDecimal.ZERO;
62	
63	    @Column(name = "discount_cap")
64	    private BigDecimal discountCap;
65	
66	    @Column(name = "discount_reason")
67	    private String discountReason;
68	
69	    /** Whether the invoice's client is tax exempt, so no line is taxed; read from the client. */
70	    @Formula("(SELECT c.tax_exempt FROM client c WHERE c.id = client_id)")
71	    private boolean clientTaxExempt;
72	
73	    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true)
74	    @JoinColumn(name = "invoice_id", nullable = false)
75	    @OrderBy("id")
