81	    /** A new, empty draft for a client, issued and due on the given dates. */
82	    public static Invoice draft(Long clientId, boolean clientTaxExempt, LocalDate issueDate, LocalDate dueDate) {
83	        Invoice invoice = new Invoice();
84	        invoice.clientId = clientId;
85	        invoice.clientTaxExempt = clientTaxExempt;
