91	
92	    /**
93	     * A new draft for the same client with copies of this invoice's lines and the same invoice
94	     * discount, issued and due on the given dates. Payments stay with this invoice.
95	     */
96	    public Invoice duplicate(LocalDate issueDate, LocalDate dueDate) {
97	        Invoice copy = draft(clientId, clientTaxExempt, issueDate, dueDate);
98	        copy.discountPct = discountPct;
99	        copy.discountAmount = discountAmount;
