106	    public Long getId() {
107	        return id;
108	    }
109	
110	    public Long getClientId() {
111	        return clientId;
112	    }
113	
114	    public InvoiceStatus getStatus() {
115	        return status;
116	    }
117	
118	    public LocalDate getIssueDate() {
119	        return issueDate;
120	    }
121	
122	    public LocalDate getDueDate() {
123	        return dueDate;
124	    }
125	
126	    /** The percentage taken off the subtotal, 0 to 100 with up to two decimals. */
127	    public BigDecimal getDiscountPct() {
128	        return discountPct;
129	    }
130	
131	    /** The fixed amount taken off the subtotal, to the cent; 0 when the discount is a percentage. */
132	    public BigDecimal getDiscountAmount() {
133	        return discountAmount;
134	    }
135	
136	    /** The most taken off the invoice in all, line discounts included, to the cent; null when there is no cap. */
137	    public BigDecimal getDiscountCap() {
