package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than a week (the grace period) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID
}
package net.officefloor.hq.app.invoices;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An invoice's number, made from its id: INV-, the id padded to six digits, then a Luhn check
 * digit over those six digits — so invoice 7 is INV-0000075.
 */
public final class InvoiceNumber {

    private static final Pattern FORM = Pattern.compile("INV-(\\d{6})(\\d)");

    private InvoiceNumber() {
    }

    /** The number of the invoice with this id. */
    public static String of(long id) {
        String digits = String.format("%06d", id);
        return "INV-" + digits + checkDigit(digits);
    }

    /**
     * The invoice id a typed number stands for. Empty when it is not of the form INV-nnnnnnn or its
     * check digit does not match — the number was mistyped.
     */
    public static Optional<Long> idOf(String typed) {
        Matcher m = FORM.matcher(typed.trim().toUpperCase());
        if (!m.matches() || checkDigit(m.group(1)) != m.group(2).charAt(0) - '0') {
            return Optional.empty();
        }
        return Optional.of(Long.parseLong(m.group(1)));
    }

    /**
     * Luhn: from the rightmost digit, double every second digit (the rightmost, the third from the
     * right, ...), subtracting 9 from any result over 9; the check digit brings the sum of all the
     * digits up to the next multiple of ten.
     */
    static int checkDigit(String digits) {
        int sum = 0;
        for (int i = 0; i < digits.length(); i++) {
            int d = digits.charAt(digits.length() - 1 - i) - '0';
            if (i % 2 == 0) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
        }
        return (10 - sum % 10) % 10;
    }
}
package net.officefloor.hq.app.invoices;

import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.server.ResponseStatusException;

/** Turns a refused invoice change into a problem response whose detail says what is wrong. */
@RestControllerAdvice(assignableTypes = InvoiceController.class)
public class InvoiceErrors {

    private static final List<String> FIELD_ORDER = List.of("description", "qty", "unitPrice", "discountPct", "discountAmount", "discountCap", "discountReason", "discountGiven", "amount", "date", "reference", "dueDate");

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail invalid(MethodArgumentNotValidException e) {
        String detail = e.getBindingResult().getFieldErrors().stream()
                .sorted((a, b) -> Integer.compare(FIELD_ORDER.indexOf(a.getField()),
                        FIELD_ORDER.indexOf(b.getField())))
                .map(f -> f.getDefaultMessage())
                .distinct()
                .reduce((a, b) -> a + " " + b)
                .orElse("The change is not valid.");
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, detail);
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ProblemDetail unreadable(HttpMessageNotReadableException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,
                "Enter the numbers as numbers, like 1.5 and 12.35.");
    }

    @ExceptionHandler(ResponseStatusException.class)
    public ProblemDetail status(ResponseStatusException e) {
        return ProblemDetail.forStatusAndDetail(e.getStatusCode(), e.getReason());
    }

    @ExceptionHandler(InvoiceRejectedException.class)
    public ProblemDetail rejected(InvoiceRejectedException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, e.getMessage());
    }
}
package net.officefloor.hq.app.invoices;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.EntityGraph;
import org.springframework.data.jpa.repository.JpaRepository;

public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    @EntityGraph(attributePaths = "lines")
    List<Invoice> findByClientIdOrderByIdAsc(Long clientId);

    @EntityGraph(attributePaths = "lines")
    List<Invoice> findAllByOrderByIdAsc();

    @EntityGraph(attributePaths = "lines")
    Optional<Invoice> findWithLinesById(Long id);
}
-- Workspace settings, one value per name (for example the test's "today", as_of).
CREATE TABLE app_setting (
    name  VARCHAR(64)  PRIMARY KEY,
    setting_value VARCHAR(255) NOT NULL
);

CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id  BIGINT      NOT NULL REFERENCES client (id),
    status     VARCHAR(16) NOT NULL DEFAULT 'DRAFT',
    issue_date DATE,
    due_date   DATE
);

-- A line is a quantity (up to two decimals, e.g. 1.25 hours) times a unit price.
CREATE TABLE invoice_line (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id  BIGINT         NOT NULL REFERENCES invoice (id) ON DELETE CASCADE,
    description VARCHAR(255)   NOT NULL DEFAULT '',
    qty         DECIMAL(12, 2) NOT NULL,
    unit_price  DECIMAL(19, 2) NOT NULL
);
-- How much of a payment's unused credit has been refunded to the client: it can no longer be used.
ALTER TABLE payment ADD COLUMN refunded DECIMAL(19, 2) DEFAULT 0 NOT NULL;

