308	    private void applyCredit(Invoice invoice) {
309	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
310	        LocalDate now = today.date();
311	        boolean used = false;
312	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
313	            if (due.signum() <= 0) {
314	                break;
315	            }
316	            BigDecimal credit = payment.credit();
317	            if (credit.signum() <= 0) {
318	                continue;
319	            }
320	            BigDecimal part = credit.min(due);
321	            payment.apply(invoice.getId(), part, now);
322	            payments.saveAndFlush(payment);
323	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
324	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
325	            due = due.subtract(part);
326	            used = true;
