340	        if (clients.findById(clientId).isEmpty()) {
341	            return Optional.empty();
342	        }
343	        LocalDate now = today.date();
344	        if (date.isAfter(now)) {
345	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
346	        }
347	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
348	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
349	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
350	        return Optional.of(payment);
