353	    /**
354	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
355	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
356	     * such client. The amount has already been checked; a date after today or before a payment it
357	     * would come from, or an amount more than the client's credit, is refused.
358	     */
359	    @Transactional
360	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
361	        if (clients.findById(clientId).isEmpty()) {
362	            return Optional.empty();
363	        }
364	        LocalDate now = today.date();
365	        if (date.isAfter(now)) {
366	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
367	        }
368	        List<Payment> from = new ArrayList<>();
369	        List<BigDecimal> parts = new ArrayList<>();
370	        BigDecimal left = amount;
371	        BigDecimal credit = BigDecimal.ZERO;
372	        for (Payment payment : payments.findForClient(clientId)) {
373	            BigDecimal unused = payment.credit();
374	            if (unused.signum() <= 0) {
375	                continue;
376	            }
377	            credit = credit.add(unused);
378	            if (left.signum() <= 0) {
379	                continue;
380	            }
381	            BigDecimal part = unused.min(left);
382	            if (date.isBefore(payment.getDate())) {
383	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
384	                        + payment.getDate() + " it would come from.");
385	            }
386	            from.add(payment);
387	            parts.add(part);
388	            left = left.subtract(part);
389	        }
390	        if (left.signum() > 0) {
391	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
392	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
393	        }
394	        for (int i = 0; i < from.size(); i++) {
395	            Payment payment = from.get(i);
396	            payment.refund(parts.get(i));
397	            payments.saveAndFlush(payment);
398	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
399	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
400	        }
401	        return Optional.of(clientId);
402	    }
