466	    @Transactional(readOnly = true)
467	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
468	        Map<Long, BigDecimal> paid = new HashMap<>();
469	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
470	        if (!list.isEmpty()) {
471	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
472	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
473	            }
474	        }
475	        return paid;
476	    }
477	
478	    /**
479	     * Records a payment of the amount on the date against a sent invoice that still has something
480	     * due, and records it in the audit; empty if no such invoice. The amount has already been
481	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
482	     * invoice already paid, or a date after today
483	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
484	     * already been checked; one that belongs to a different invoice is refused.
485	     */
486	    @Transactional
487	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
488	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
489	        found.ifPresent(invoice -> {
490	            if (invoice.isDraft()) {
491	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
492	            }
493	            if (invoice.isVoid()) {
494	                throw new InvoiceRejectedException("A void invoice takes no payments.");
495	            }
496	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
497	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
498	            if (due.signum() <= 0) {
499	                throw new InvoiceRejectedException("This invoice has already been paid.");
500	            }
501	            BigDecimal applied = amount.min(due);
502	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
503	                throw new InvoiceRejectedException("A part payment must be at least $"
504	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
505	                        + " (10% of the total), unless it settles the invoice.");
506	            }
507	            LocalDate now = today.date();
508	            if (date.isAfter(now)) {
509	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
510	            }
511	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
512	                throw new InvoiceRejectedException(
513	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
514	            }
515	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
516	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
517	                        + " is the reference of a different invoice; this invoice's is "
518	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
519	            }
520	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
521	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
522	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
523	            recordWriteOff(invoice);
524	            recordCreditHeld(payment);
525	        });
526	        return found;
527	    }
528	
529	    /**
530	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
531	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
532	     * paying each off in full before the next.
533	     * What it pays beyond everything the client owes is held on the client's account as credit; the
534	     * rest is checked and recorded as a split payment over the invoices it reaches.
535	     * References (empty when none, each already checked) instead limit the payment to the client's
536	     * invoices with those references, applied in the same order; one that is not the reference of any
537	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
538	     * as credit.
539	     * The payment keeps the reference of the first invoice it reaches.
540	     */
541	    @Transactional
542	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
543	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
544	        List<Invoice> candidates = ofClient;
545	        if (!references.isEmpty()) {
546	            Set<Long> named = new HashSet<>();
547	            for (String reference : references) {
548	                Invoice invoice = ofClient.stream()
549	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
550	                        .findFirst()
551	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
552	                                + " is not the reference of any of this client's invoices."));
553	                String number = InvoiceNumber.of(invoice.getId());
554	                if (invoice.isDraft()) {
555	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
556	                }
557	                if (invoice.isVoid()) {
558	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
559	                }
560	                named.add(invoice.getId());
561	            }
562	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
563	        }
564	        List<Invoice> sent = candidates.stream()
565	                .filter(i -> !i.isDraft() && !i.isVoid())
566	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
567	                        .thenComparing(Invoice::getId))
568	                .toList();
569	        Map<Long, BigDecimal> paid = paid(sent);
570	        BigDecimal owed = BigDecimal.ZERO;
571	        BigDecimal left = amount;
572	        List<PaymentAllocation> parts = new ArrayList<>();
573	        for (Invoice invoice : sent) {
574	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
575	            if (due.signum() <= 0) {
576	                continue;
577	            }
578	            owed = owed.add(due);
579	            if (left.signum() > 0) {
580	                BigDecimal part = left.min(due);
581	                parts.add(new PaymentAllocation(invoice.getId(), part));
582	                left = left.subtract(part);
583	            }
584	        }
585	        if (owed.signum() <= 0) {
586	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
587	                    : "Those invoices have already been paid.");
588	        }
589	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
590	        return recordSpread(clientId, amount, date, reference, parts, true);
591	    }
592	
593	    /**
594	     * Records one payment of the amount on the date spread over several of the client's invoices, and
595	     * records each part in the audit. The amounts have already been checked to be more than zero; they
596	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
597	     * and be no more than what it still has due. The date must be no later than today nor before any
598	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
599	     * be the reference of one of the invoices.
600	     */
601	    @Transactional
602	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
603	            List<PaymentAllocation> parts) {
604	        return recordSpread(clientId, amount, date, reference, parts, false);
605	    }
606	
607	    /**
608	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
609	     * credit may be held the parts may add up to less than the payment: the rest is held on the
610	     * client's account as credit and recorded in the audit.
611	     */
612	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
613	            List<PaymentAllocation> parts, boolean holdCredit) {
614	        if (parts.isEmpty()) {
615	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
616	        }
617	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
618	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
619	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
620	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
621	        }
622	        LocalDate now = today.date();
623	        if (date.isAfter(now)) {
624	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
625	        }
626	        Set<Long> seen = new HashSet<>();
627	        List<Invoice> spreadOver = new ArrayList<>();
628	        for (PaymentAllocation part : parts) {
629	            if (!seen.add(part.getInvoiceId())) {
630	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
631	            }
632	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
633	                    .filter(i -> i.getClientId().equals(clientId))
634	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
635	            String number = InvoiceNumber.of(invoice.getId());
636	            if (invoice.isDraft()) {
637	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
638	            }
639	            if (invoice.isVoid()) {
640	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
641	            }
642	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
643	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
644	            if (part.getAmount().compareTo(due) > 0) {
645	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
646	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
647	            }
648	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
649	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
650	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
651	                        + " (10% of its total), unless it settles the invoice.");
652	            }
653	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
654	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
655	                        + " (" + invoice.getIssueDate() + ").");
656	            }
657	            spreadOver.add(invoice);
658	        }
659	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
660	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
661	                    + " is not the reference of any of the invoices being paid.");
662	        }
663	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
664	        for (PaymentAllocation part : parts) {
665	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
666	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
667	        }
668	        spreadOver.forEach(this::recordWriteOff);
669	        recordCreditHeld(payment);
670	        return payment;
671	    }
672	
673	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
674	    private void recordCreditHeld(Payment payment) {
675	        BigDecimal credit = payment.credit();
676	        if (credit.signum() > 0) {
677	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
678	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
679	        }
680	    }
681	
682	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
683	    private void recordWriteOff(Invoice invoice) {
684	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
685	        if (writtenOff.signum() > 0) {
686	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
687	        }
688	    }
689	
690	    /**
691	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
692	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
693	     * had any of its credit refunded, is refused.
694	     */
695	    @Transactional
696	    public Optional<Payment> reversePayment(Long paymentId) {
697	        Optional<Payment> found = payments.findById(paymentId);
698	        found.ifPresent(payment -> {
699	            if (payment.isReversed()) {
700	                throw new InvoiceRejectedException("This payment has already been reversed.");
701	            }
702	            if (payment.getRefunded().signum() > 0) {
703	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
704	            }
705	            payment.reverse();
706	            payments.saveAndFlush(payment);
707	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
708	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
709	        });
710	        return found;
711	    }
712	}
