255	    private Long insert(String table, Object id, String[] columns, Object... values) {
256	        String cols = String.join(", ", columns);
257	        String marks = String.join(", ", Collections.nCopies(columns.length, "?"));
258	        if (id != null) {
259	            Object[] args = new Object[values.length + 1];
260	            args[0] = id(id);
261	            System.arraycopy(values, 0, args, 1, values.length);
262	            jdbc.update("INSERT INTO " + table + " (id, " + cols + ") VALUES (?, " + marks + ")", args);
263	            return id(id);
264	        }
265	        jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")", values);
266	        return jdbc.queryForObject("SELECT MAX(id) FROM " + table, Long.class);
267	    }
