269	    /** A whole number of days, not negative; null when left out. */
270	    private static Integer days(Object value, String field) {
271	        if (value == null) {
272	            return null;
273	        }
274	        try {
275	            int days = new BigDecimal(value.toString()).intValueExact();
276	            if (days < 0) {
277	                throw refuse(field + " cannot be negative, not " + value);
278	            }
279	            return days;
280	        } catch (NumberFormatException | ArithmeticException e) {
281	            throw refuse(field + " must be a whole number of days, not " + value);
282	        }
283	    }
