296	    private static void only(Map<String, Object> row, Set<String> fields, String where) {
297	        for (String field : row.keySet()) {
298	            if (!fields.contains(field)) {
299	                throw refuse("unsupported field: " + where + "." + field);
300	            }
301	        }
302	    }
