304	    private static Long id(Object value) {
305	        if (value instanceof Number n) {
306	            return n.longValue();
307	        }
308	        try {
309	            return Long.valueOf(value.toString());
310	        } catch (NumberFormatException e) {
311	            throw refuse("not an id: " + value);
312	        }
313	    }
314	
315	    private static LocalDate date(Object value, String field) {
316	        try {
317	            return LocalDate.parse(value.toString());
318	        } catch (DateTimeParseException e) {
319	            throw refuse(field + " must be a yyyy-mm-dd date, not " + value);
320	        }
321	    }
