323	    /** A number stored to the cent; refuses a value it could only store by rounding. */
324	    private static BigDecimal cents(Object value, String field) {
325	        if (value == null) {
326	            throw refuse(field + " is required");
327	        }
328	        BigDecimal number;
329	        try {
330	            number = new BigDecimal(value.toString());
331	        } catch (NumberFormatException e) {
332	            throw refuse(field + " must be a number, not " + value);
333	        }
334	        if (number.stripTrailingZeros().scale() > 2) {
335	            throw refuse(field + " can have at most two decimals, not " + value);
336	        }
337	        return number;
338	    }
