340	    /** A percentage from 0 to 100 with at most two decimals; none given is zero. */
341	    private static BigDecimal percent(Object value, String field) {
342	        if (value == null) {
343	            return BigDecimal.ZERO;
344	        }
345	        BigDecimal number = cents(value, field);
346	        if (number.signum() < 0 || number.compareTo(BigDecimal.valueOf(100)) > 0) {
347	            throw refuse(field + " must be from 0 to 100, not " + value);
348	        }
349	        return number;
350	    }
