373	        for (Object o : list) {
374	            if (!(o instanceof Map<?, ?> m)) {
375	                throw refuse(key + " must be a list of rows");
376	            }
377	            out.add((Map<String, Object>) m);
378	        }
379	        return out;
380	    }
