278	    @GetMapping("/api/clients/balances")
279	    public List<ClientBalance> balances() {
280	        BigDecimal rate = taxRate.percent();
281	        List<Invoice> sent = invoices.all().stream().filter(i -> !i.isDraft() && !i.isVoid()).toList();
282	        Map<Long, BigDecimal> paid = invoices.paid(sent);
283	        LocalDate on = today.date();
284	        Map<Long, BigDecimal[]> owed = new TreeMap<>();
285	        for (Invoice i : sent) {
286	            BigDecimal due = i.amountDue(paid.get(i.getId()), rate);
287	            BigDecimal[] sums = owed.computeIfAbsent(i.getClientId(),
288	                    k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
289	            sums[0] = sums[0].add(due);
290	            if (i.statusWhenPaid(paid.get(i.getId()), rate, on) == InvoiceStatus.OVERDUE) {
291	                sums[1] = sums[1].add(due);
292	            }
293	        }
294	        Map<Long, BigDecimal> credits = invoices.credits();
295	        credits.keySet().forEach(clientId -> owed.computeIfAbsent(clientId,
296	                k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) }));
297	        return owed.entrySet().stream().map(e -> {
298	            BigDecimal credit = credits.getOrDefault(e.getKey(), BigDecimal.ZERO).setScale(2);
299	            return new ClientBalance(e.getKey(), e.getValue()[0].subtract(credit).toPlainString(),
300	                    e.getValue()[1].toPlainString(), credit.toPlainString());
301	        }).toList();
302	    }
