433	            <p role="alert" data-testid="discount-form-error">{{ discountError() }}</p>
434	          }
435	        </form>
436	      }
437	    </section>
438	  `,
439	})
440	export class InvoicePanel {
441	  private readonly service = inject(InvoiceService);
442	
443	  readonly invoiceId = input.required<number>();
444	  // Bumped when the invoice was changed elsewhere (sent with the client's other drafts), to load it again.
445	  readonly reload = input(0);
446	  // The invoice after a change made here, so the list can show its new total.
447	  readonly changed = output<InvoiceDetail>();
448	  // The parts of a payment filled in on the list; when any is, a payment is spread over them.
449	  readonly allocations = input<NewAllocation[]>([]);
450	  // The client's invoices after a payment spread over several of them.
451	  readonly split = output<InvoiceSummary[]>();
452	  // A new draft copied from this invoice, to be listed and opened.
453	  readonly duplicated = output<InvoiceDetail>();
454	
455	  protected readonly invoice = signal<InvoiceDetail | null>(null);
456	  protected readonly saving = signal(false);
457	  protected readonly error = signal('');
458	  // The line loaded into the line form to be changed, or null when the form adds a new line.
459	  protected readonly editingLineId = signal<number | null>(null);
460	  protected readonly savingDiscount = signal(false);
461	  protected readonly discountError = signal('');
462	  protected readonly savingDue = signal(false);
463	  protected readonly dueError = signal('');
464	  protected readonly sending = signal(false);
465	  protected readonly sendError = signal('');
466	  protected readonly duplicating = signal(false);
467	  protected readonly duplicateError = signal('');
468	  protected readonly voiding = signal(false);
469	  protected readonly voidError = signal('');
470	  protected readonly reversing = signal(false);
471	  protected readonly reverseError = signal('');
472	  protected readonly statusLabel = statusLabel;
473	  protected readonly money = money;
474	
475	  protected readonly form = new FormGroup({
476	    description: new FormControl('', { nonNullable: true }),
477	    qty: new FormControl('', { nonNullable: true }),
478	    unitPrice: new FormControl('', { nonNullable: true }),
479	    taxExempt: new FormControl(false, { nonNullable: true }),
480	    discountPct: new FormControl('', { nonNullable: true }),
481	    taxRate: new FormControl('', { nonNullable: true }),
