489	  });
490	
491	  protected readonly dueForm = new FormGroup({
492	    dueDate: new FormControl('', { nonNullable: true }),
493	  });
494	
495	  constructor() {
496	    effect((onCleanup) => {
497	      const id = this.invoiceId();
498	      this.reload();
499	      this.invoice.set(null);
500	      this.form.reset();
501	      this.editingLineId.set(null);
502	      this.error.set('');
503	      this.discountForm.reset();
504	      this.discountError.set('');
505	      this.dueForm.reset();
506	      this.dueError.set('');
507	      this.sendError.set('');
