516	  // Loads a line into the line form, so submitting it changes that line instead of adding one.
517	  protected editLine(line: InvoiceLineView): void {
518	    this.form.setValue({
519	      description: line.description,
520	      qty: line.qty,
521	      unitPrice: line.unitPrice,
522	      taxExempt: line.taxExempt,
