536	  protected saveLine(invoiceId: number): void {
537	    const raw = this.form.getRawValue();
538	    const line: NewLine = {
539	      description: raw.description.trim(),
540	      qty: raw.qty.trim(),
541	      unitPrice: raw.unitPrice.trim().replace(/^\$/, ''),
542	      taxExempt: raw.taxExempt,
543	    };
544	    const discountPct = raw.discountPct.trim().replace(/%$/, '').trim();
545	    if (discountPct) {
546	      line.discountPct = discountPct;
547	    }
548	    const taxRate = raw.taxRate.trim().replace(/%$/, '').trim();
