575	        const fallback = lineId === null ? 'The line could not be added.' : 'The line could not be changed.';
576	        this.error.set(typeof detail === 'string' && detail ? detail : fallback);
577	        this.saving.set(false);
578	      },
579	    });
580	  }
581	
582	  protected removeLine(invoiceId: number, lineId: number): void {
583	    this.saving.set(true);
584	    this.error.set('');
585	    this.service.removeLine(invoiceId, lineId).subscribe({
586	      next: (detail) => {
587	        this.invoice.set(detail);
588	        if (this.editingLineId() === lineId) {
589	          this.form.reset();
590	          this.editingLineId.set(null);
591	        }
592	        this.changed.emit(detail);
593	        this.saving.set(false);
594	      },
595	      error: (e: HttpErrorResponse) => {
596	        const detail: unknown = e.error?.detail;
597	        this.error.set(
598	          typeof detail === 'string' && detail ? detail : 'The line could not be removed.',
599	        );
600	        this.saving.set(false);
601	      },
602	    });
603	  }
604	
605	  protected setDiscount(invoiceId: number): void {
606	    const raw = this.discountForm.getRawValue();
607	    const pct = raw.pct.trim().replace(/%$/, '').trim();
608	    const amount = raw.amount.trim().replace(/^\$/, '').trim();
609	    const cap = raw.cap.trim().replace(/^\$/, '').trim();
610	    const problem = problemWithDiscountForm(pct, amount, cap);
611	    if (problem) {
612	      this.discountForm.markAllAsTouched();
613	      this.discountError.set(problem);
614	      return;
615	    }
616	    this.savingDiscount.set(true);
617	    this.discountError.set('');
618	    const discount: NewDiscount = pct ? { discountPct: pct } : { discountAmount: amount };
619	    if (cap) {
620	      discount.discountCap = cap;
621	    }
622	    const reason = raw.reason.trim();
623	    if (reason) {
624	      discount.discountReason = reason;
625	    }
626	    this.service.setDiscount(invoiceId, discount).subscribe({
627	      next: (detail) => {
628	        this.invoice.set(detail);
629	        this.changed.emit(detail);
630	        this.discountForm.reset();
631	        this.savingDiscount.set(false);
632	      },
633	      error: (e: HttpErrorResponse) => {
634	        const detail: unknown = e.error?.detail;
635	        this.discountError.set(
636	          typeof detail === 'string' && detail ? detail : 'The discount could not be applied.',
637	        );
638	        this.savingDiscount.set(false);
639	      },
640	    });
641	  }
642	
643	  protected paymentRecorded(detail: InvoiceDetail): void {
644	    this.invoice.set(detail);
645	    this.changed.emit(detail);
646	  }
647	
648	  // A payment was spread over several invoices: show this one again with its share.
649	  protected splitRecorded(invoiceId: number, list: InvoiceSummary[]): void {
650	    this.split.emit(list);
651	    this.service.open(invoiceId).subscribe((detail) => this.invoice.set(detail));
652	  }
653	
654	  protected setDueDate(invoiceId: number): void {
655	    const dueDate = this.dueForm.getRawValue().dueDate.trim();
656	    if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
657	      this.dueForm.markAllAsTouched();
658	      this.dueError.set('Enter the due date as a date, like 2026-04-30.');
659	      return;
