662	    this.dueError.set('');
663	    this.service.setDueDate(invoiceId, dueDate).subscribe({
664	      next: (detail) => {
665	        this.invoice.set(detail);
666	        this.changed.emit(detail);
667	        this.dueForm.reset();
668	        this.savingDue.set(false);
669	      },
670	      error: (e: HttpErrorResponse) => {
671	        const detail: unknown = e.error?.detail;
672	        this.dueError.set(
673	          typeof detail === 'string' && detail ? detail : 'The due date could not be set.',
674	        );
675	        this.savingDue.set(false);
